import { useEffect, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { isEmpty } from 'lodash'
import { Container } from '../../../../../../components'
import StepsHeader from '../../../../../../components/StepsHeader'
import PropertyDetailForm from '../../../../../CommonContainer/PropertyDetailForm'
import { PROPERTY_LANG } from '../../../../../Private/Property/lang'
import { setToLocalStorage } from '../../../../../../helpers/localstorage'
import { CUSTOMER_FLOW } from '../../../../../../constants/cookies'
import { PolicyContextProvider } from '../../../../../Private/Policy/context'
import useDraftApi from '../../../../../Private/Property/Pages/hooks/useDraftApi'

function PropertyCustomerForm () {
  const history = useHistory()
  const { draftId } = useParams()

  useEffect(() => {
    setToLocalStorage(CUSTOMER_FLOW, 'true')
  }, [])

  const [draftData, setDraftData] = useState({})

  const { isGetDraftLoader, isSaveLoader, handleSaveToDraft } = useDraftApi({
    draftId: draftId,
    onGetDraftDetailSuccess: (data) => {
      setDraftData(data)
    },
    onSaveSuccess: ({ draftId }) => {
      history.push(`/customer/property/${draftId}/2/summary/`)
    }
  })

  const handleSubmit = (data) => {
    handleSaveToDraft(data, 'mv_quote_summary', 'mv_quote_summary')
  }

  return (
    <Container
      title={PROPERTY_LANG.propertyInsurance}
      loader={isGetDraftLoader || isSaveLoader}
      hideBottomTabs
      showInnerHeader
      displayBackButton
    >
      <StepsHeader
        current='1'
        totalSteps='4'
        leftText={PROPERTY_LANG.insuredInformation}
        className='steps-header'
      />
      {
        !isEmpty(draftData?.policy_details) && (
          <PropertyDetailForm
            policyDetails={draftData?.policy_details}
            onSubmitForm={handleSubmit}
          />
        )
      }
    </Container>
  )
}

function WrappedPropertyCustomerForm (props) {
  return (
    <PolicyContextProvider>
      <PropertyCustomerForm {...props} />
    </PolicyContextProvider>
  )
}

export default WrappedPropertyCustomerForm
